{"command": "create", "path": "/app/solution.py", "file_text": """"Dialogue script parser.

Converts a text-format dialogue script into a validated graph.

Input format (per node block):

    [NodeId]
    Speaker: text -> TargetNode              # line node
    OR
    1. Option text -> TargetA                 # choice node
    2. [Tag] Option text -> TargetB

Output JSON:
    {"nodes": [{"id","text","speaker","type"}],
     "edges": [{"from","to","text"}]}
"""

from __future__ import annotations

import json
import re
import sys
from collections import deque
from typing import Any

HEADER_RE = re.compile(r"^\[([^\]]+)\]\s*$")
CHOICE_RE = re.compile(r"^(\d+)\.\s*(.+?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^([^:]+):\s*(.+?)\s*->\s*(\S+)\s*$")


def parse_script(text: str) -> dict[str, Any]:
    """Parse a dialogue script into a graph dict with nodes and edges."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []
    seen_ids: set[str] = set()

    current_id: str | None = None
    current_speaker: str | None = None
    current_text: str | None = None
    current_target: str | None = None
    current_choices: list[tuple[str, str]] = []

    def flush() -> None:
        nonlocal current_id, current_speaker, current_text, current_target, current_choices
        if current_id is None:
            return
        if current_id in seen_ids:
            raise ValueError(f"Duplicate node id: {current_id}")
        seen_ids.add(current_id)

        if current_choices:
            nodes.append({
                "id": current_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            })
            for choice_text, target in current_choices:
                edges.append({
                    "from": current_id,
                    "to": target,
                    "text": choice_text,
                })
        else:
            nodes.append({
                "id": current_id,
                "text": current_text or "",
                "speaker": current_speaker or "",
                "type": "line",
            })
            if current_target:
                edges.append({
                    "from": current_id,
                    "to": current_target,
                    "text": "",
                })

        current_id = None
        current_speaker = None
        current_text = None
        current_target = None
        current_choices = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue

        header = HEADER_RE.match(line)
        if header:
            flush()
            current_id = header.group(1).strip()
            continue

        if current_id is None:
            # Stray content before any node header is ignored.
            continue

        choice = CHOICE_RE.match(line)
        if choice:
            current_choices.append((choice.group(2).strip(), choice.group(3).strip()))
            continue

        speaker_line = LINE_RE.match(line)
        if speaker_line:
            current_speaker = speaker_line.group(1).strip()
            current_text = speaker_line.group(2).strip()
            current_target = speaker_line.group(3).strip()
            continue

    flush()

    # Ensure every referenced target has a corresponding node. In this script
    # "End" is referenced but never declared; add it as a terminal line node.
    existing = {n["id"] for n in nodes}
    for edge in edges:
        if edge["to"] not in existing:
            nodes.append({
                "id": edge["to"],
                "text": "",
                "speaker": "",
                "type": "line",
            })
            existing.add(edge["to"])

    return {"nodes": nodes, "edges": edges}


def validate(graph: dict[str, Any]) -> list[str]:
    """Return a list of validation errors (empty if the graph is valid)."""
    errors: list[str] = []
    nodes = graph["nodes"]
    edges = graph["edges"]

    if not nodes:
        errors.append("Graph has no nodes")
        return errors

    node_ids = {n["id"] for n in nodes}
    if len(node_ids) != len(nodes):
        errors.append("Duplicate node ids present")

    # Every edge target must exist as a node.
    for edge in edges:
        if edge["from"] not in node_ids:
            errors.append(f"Edge source '{edge['from']}' not a known node")
        if edge["to"] not in node_ids:
            errors.append(f"Edge target '{edge['to']}' not a known node")

    # All nodes must be reachable from the first node.
    start = nodes[0]["id"]
    adjacency: dict[str, list[str]] = {nid: [] for nid in node_ids}
    for edge in edges:
        if edge["from"] in adjacency:
            adjacency[edge["from"]].append(edge["to"])

    reachable: set[str] = set()
    queue = deque([start])
    while queue:
        current = queue.popleft()
        if current in reachable:
            continue
        reachable.add(current)
        for nxt in adjacency.get(current, []):
            if nxt not in reachable:
                queue.append(nxt)

    unreachable = node_ids - reachable
    if unreachable:
        errors.append(f"Unreachable nodes from '{start}': {sorted(unreachable)}")

    return errors


def to_dot(graph: dict[str, Any]) -> str:
    """Produce a Graphviz DOT representation of the dialogue graph."""
    speaker_colors = {
        "Narrator": "lightyellow",
        "Guard": "lightcoral",
        "Stranger": "plum",
        "Merchant": "lightgreen",
        "Barkeep": "peachpuff",
        "Kira": "lightcyan",
    }

    def esc(value: str) -> str:
        return value.replace("\\", "\\\\").replace("\"", "\\\"")

    def truncate(value: str, limit: int) -> str:
        return value if len(value) <= limit else value[: limit - 3] + "..."

    lines: list[str] = [
        "digraph Dialogue {",
        "  rankdir=TB;",
        "  node [fontname=\"Arial\", fontsize=10];",
        "  edge [fontname=\"Arial\", fontsize=8];",
    ]

    for node in graph["nodes"]:
        nid = node["id"]
        if nid == "End":
            lines.append(
                f'  "{esc(nid)}" [label="END", shape=doublecircle, '
                'style=filled, fillcolor=lightgray];'
            )
            continue
        if node["type"] == "choice":
            lines.append(
                f'  "{esc(nid)}" [label="{esc(nid)}", shape=diamond, '
                'style=filled, fillcolor=lightblue];'
            )
        else:
            speaker = node.get("speaker", "")
            text = truncate(node.get("text", ""), 40)
            if speaker and text:
                label = f"{nid}\\n{speaker}: {text}"
            elif speaker:
                label = f"{nid}\\n{speaker}"
            else:
                label = nid
            fill = speaker_colors.get(speaker, "white")
            lines.append(
                f'  "{esc(nid)}" [label="{esc(label)}", shape=box, '
                f'style="filled,rounded", fillcolor={fill}];'
            )

    for edge in graph["edges"]:
        src = esc(edge["from"])
        dst = esc(edge["to"])
        text = truncate(edge.get("text", ""), 30)
        if text:
            if "[" in text and "]" in text:
                lines.append(
                    f'  "{src}" -> "{dst}" [label="{esc(text)}", '
                    'color=darkblue, fontcolor=darkblue, style=bold];'
                )
            else:
                lines.append(
                    f'  "{src}" -> "{dst}" [label="{esc(text)}", '
                    'color=gray40, fontcolor=gray40];'
                )
        else:
            lines.append(f'  "{src}" -> "{dst}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


def main(argv: list[str]) -> int:
    script_path = argv[1] if len(argv) > 1 else "/app/script.txt"
    json_path = argv[2] if len(argv) > 2 else "/app/dialogue.json"
    dot_path = argv[3] if len(argv) > 3 else "/app/dialogue.dot"

    with open(script_path, encoding="utf-8") as fh:
        text = fh.read()

    graph = parse_script(text)
    errors = validate(graph)
    if errors:
        print("Validation errors:", file=sys.stderr)
        for err in errors:
            print(f"  - {err}", file=sys.stderr)
        return 1

    with open(json_path, "w", encoding="utf-8") as fh:
        json.dump(graph, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    with open(dot_path, "w", encoding="utf-8") as fh:
        fh.write(to_dot(graph))

    print(
        f"Parsed {len(graph['nodes'])} nodes and {len(graph['edges'])} edges. "
        f"Wrote {json_path} and {dot_path}."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
