def parse_script(text: str) -> dict[str, Any]:
    """Parse a dialogue script into a graph dict with nodes and edges."""
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []
    seen_ids: set[str] = set()

    current_id: str | None = None
    current_speaker: str | None = None
    current_text: str | None = None
    current_target: str | None = None
    current_choices: list[tuple[str, str]] = []

    def flush() -> None:
        nonlocal current_id, current_speaker, current_text, current_target, current_choices
        if current_id is None:
            return
        if current_id in seen_ids:
